def app(slug, name, typ, title, description, h1, lead, answer, intro, features, platforms, cost, pros, cons,
        unique_title, unique, faq, related, card, alt='android', dev=None, extra_steps=None):
    t = TYPES[typ]
    dev_line = f' Entwickelt wird die App von {dev}.' if dev else ''
    sections = [
        ('was-ist', f'Was ist {name}?', f'<p>{intro}{dev_line}</p>' + checks(*features)
         + f'<p><b>Login-Arten:</b> {t["login"]}. Wie sich M3U und Xtream Codes unterscheiden, erklären die Ratgeber <a href="/m3u-playlist/">M3U Playlist</a> und <a href="/xtream-codes-iptv/">Xtream Codes</a>.</p>'),
        ('geraete', f'{name}: unterstützte Geräte und Download', table(['Gerät / System', 'Bezugsquelle', 'Hinweis'], platforms, f'{name} unterstützte Geräte') + SAFE),
        ('einrichten', f'{name} einrichten: Playlist hinzufügen Schritt für Schritt', steps(*(extra_steps or t['steps'](name)))),
        ('besonderheit', unique_title, unique),
        ('einstellungen', f'Die besten {name} Einstellungen', checks(*t['settings'])),
        ('probleme', f'{name} funktioniert nicht? Lösungen', table(['Problem', 'Lösung'], t['problems'], f'{name} Probleme') + LOGIN),
        ('kosten', f'{name}: Kosten, Test und Erfahrungen', f'<p>{cost}</p>' + proscons(pros, cons)),
        ('alternativen', f'{name} Alternativen im Vergleich', f'<p>Wenn {name} auf Ihrem Gerät nicht verfügbar ist oder Ihnen nicht gefällt, sind diese Player die naheliegende Alternative:</p>'
         + table(['App', 'Geräte', 'Stärke'], [r for r in ALT[alt] if f'/{slug}/' not in r[0]][:4], f'Alternativen zu {name}')
         + '<p>Alle Apps im Überblick: <a href="/iptv-apps/">IPTV Apps &amp; Player</a>.</p>'),
    ]
    return dict(slug=slug, parent='apps', kind='guide', title=title, description=description, eyebrow='APP-ANLEITUNG',
                h1=h1, lead=lead, answer=answer, sections=sections, faq=faq, related=related, card=card)


def de_faq(name):
    return (f'Funktioniert {name} in Deutschland?', f'Ja. {name} ist ein Player ohne eigene Inhalte und funktioniert mit jedem IPTV-Zugang, der das passende Format liefert. Die App selbst ist legal; entscheidend ist, dass Ihr Anbieter die Inhalte rechtmäßig bereitstellt.')


